const HOST = 'db';
const USER = 'admin';
const PASSWORD = '123';
const DATABASE = 'martech_data';
const { Client } = require('pg');

let sqlSchemaPrompt;

async function getSQLPrompt() {
  try {
    const client = new Client({
      host: HOST,
      user: USER,
      password: PASSWORD,
      database: DATABASE
    });
    await client.connect();

    const tableName = 'paid_social'; // Replace with your actual table name

    // Get schema info
    const schemaQuery = `SELECT column_name, data_type, is_nullable FROM information_schema.columns WHERE table_name = '${tableName}'`;
    const schemaInfo = await client.query(schemaQuery);

    const createColumns = schemaInfo.rows.map(row => `${row.column_name} ${row.data_type} ${row.is_nullable === 'NO' ? 'NOT NULL' : ''}`);
    const sqlCreateTableQuery = `CREATE TABLE ${tableName} (${createColumns.join(', ')})`;

    // Get first 3 rows
    const selectQuery = `SELECT * FROM ${tableName} LIMIT 3`;
    const rows = await client.query(selectQuery);

    const rowValues = rows.rows.map(row => Object.values(row).join(' '));

    sqlSchemaPrompt = `${sqlCreateTableQuery}\n${selectQuery}\n${rowValues.join('\n')}`;

    console.log("PROMPT: " + sqlSchemaPrompt)

    await client.end();
    return sqlSchemaPrompt;
  } catch (e) {
    console.error(e);
    throw e;
  }
}

getSQLPrompt().then(result => result);

